Exact arithmetic on exported decimal tables; does not authorize K-minus continuation. #!/usr/bin/env python3
"""Prospective Stage 0 extraction and arithmetic only; no hardware authorization."""
import argparse
import csv
import hashlib
import json
from decimal import Decimal, localcontext
from fractions import Fraction
from pathlib import Path

MODES = ('u1', 'u2', 'u3')

def rational(x):
    if isinstance(x, bool) or x is None:
        raise ValueError('Expected a finite decimal number')
    try:
        value = Decimal(str(x))
        if not value.is_finite():
            raise ValueError('Nonfinite value')
        return Fraction(value)
    except (ArithmeticError, ValueError) as exc:
        raise ValueError('Expected a finite decimal number') from exc

def show(x):
    with localcontext() as ctx:
        ctx.prec = 28
        return str(Decimal(x.numerator) / Decimal(x.denominator))

def exact(x):
    return {'numerator': x.numerator, 'denominator': x.denominator,
            'decimal_display': show(x)}

def peak(rows):
    if len(rows) != 401:
        raise ValueError('Expected 401 sweep points')
    fs = [rational(r['f_hz']) for r in rows]
    ys = [rational(r['amplitude_v_rms']) for r in rows]
    if fs != [Fraction(8000 + 10*k) for k in range(401)]:
        raise ValueError('Grid must be ordered 8000:10:12000 Hz')
    if min(ys) < 0:
        raise ValueError('Negative amplitude')
    top = max(ys)
    if ys.count(top) != 1:
        raise ValueError('Largest amplitude is tied')
    k = ys.index(top)
    if k in (0, 400):
        raise ValueError('Largest amplitude is at band endpoint')
    ym, y0, yp = ys[k-1:k+2]
    if not (y0 > ym and y0 > yp):
        raise ValueError('Peak is not strict')
    d = ym - 2*y0 + yp
    offset = (ym-yp)/(2*d)
    if d >= 0 or abs(offset) >= Fraction(1, 2):
        raise ValueError('Invalid parabolic interpolation')
    return fs[k] + 10*offset, k

def gate(fs):
    if len(fs) != 3 or any(f < 8000 or f > 12000 for f in fs):
        raise ValueError('Expected three in-band positive frequencies')
    delta = (max(fs)-min(fs))/(sum(fs)/3)
    return {'delta4': exact(delta), 'threshold': '0.015',
            'arithmetic_gate': 'STAGE0_PASS' if delta <= Fraction(3, 200) else 'STAGE0_FAIL',
            'execution_status': 'PROVENANCE_AND_PREREQUISITES_NOT_VERIFIED',
            'kminus_continuation_authorized_by_this_tool': False,
            'physical_promotion': 0}

def score_template(obj):
    rows = obj.get('measurements', [])
    if len(rows) != 3 or [r.get('mode') for r in rows] != list(MODES):
        raise ValueError('Require exactly u1, u2, u3 in order')
    if obj.get('frequency_unit') != 'Hz':
        raise ValueError('Frequency unit must be Hz')
    if any(r.get('frequency_hz') is None for r in rows):
        return {'arithmetic_gate': 'UNSCORED', 'reason': 'Missing measured frequencies',
                'kminus_continuation_authorized_by_this_tool': False, 'physical_promotion': 0}
    return gate([rational(r['frequency_hz']) for r in rows])

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest='command', required=True)
    p = sub.add_parser('extract')
    p.add_argument('csvs', nargs=3, help='u1.csv u2.csv u3.csv, in that order')
    p = sub.add_parser('score')
    p.add_argument('result_json')
    args = parser.parse_args()
    try:
        if args.command == 'score':
            obj = json.loads(Path(args.result_json).read_text(), parse_float=Decimal)
            result = score_template(obj)
        else:
            measurements, values = [], []
            for mode, name in zip(MODES, args.csvs):
                path = Path(name)
                with path.open(newline='') as handle:
                    reader = csv.DictReader(handle)
                    if reader.fieldnames != ['f_hz', 'amplitude_v_rms']:
                        raise ValueError('CSV header must be f_hz,amplitude_v_rms')
                    rows = list(reader)
                if any(set(r) != {'f_hz', 'amplitude_v_rms'} for r in rows):
                    raise ValueError('Malformed CSV row')
                f, k = peak(rows)
                values.append(f)
                measurements.append({'mode': mode, 'frequency_hz_exact': exact(f),
                    'peak_grid_index': k, 'csv_file': path.name,
                    'csv_sha256': hashlib.sha256(path.read_bytes()).hexdigest()})
            result = {'frequency_unit': 'Hz', 'measurements': measurements, **gate(values)}
    except (ValueError, KeyError, TypeError, OSError, csv.Error) as exc:
        result = {'arithmetic_gate': 'INVALID_ACQUISITION', 'reason': str(exc),
                  'kminus_continuation_authorized_by_this_tool': False, 'physical_promotion': 0}
    print(json.dumps(result, indent=2))
    return 0 if result['arithmetic_gate'] == 'STAGE0_PASS' else 1

if __name__ == '__main__':
    raise SystemExit(main())

