"""
UD gate->burden v0.2 analyzer.
Primary identification uses matched TREAT-CTRL attributable receipts.
No theory targets embedded.
"""
import csv, sys
from collections import defaultdict

def num(x):
    return None if x in ("",None) else float(x)

def diff(t,c,key):
    a,b=num(t.get(key)),num(c.get(key))
    return None if a is None or b is None else a-b

def slope(xs,ys):
    den=sum(x*x for x in xs)
    if den==0: return None
    return sum(x*y for x,y in zip(xs,ys))/den

if __name__=="__main__":
    if len(sys.argv)!=2:
        raise SystemExit("usage: analyzer.py telemetry.csv")
    rows=list(csv.DictReader(open(sys.argv[1],newline="",encoding="utf-8")))
    pairs=defaultdict(dict)
    for r in rows:
        pairs[r["pair_id"]][r["run_role"]]=r

    derived=defaultdict(list)
    for pid,p in pairs.items():
        if not {"TREAT","CTRL"} <= set(p): continue
        t,c=p["TREAT"],p["CTRL"]
        cls=t["event_class"]
        dHs=diff(t,c,"delta_H_S")
        dq={i:diff(t,c,f"delta_q{i}") for i in range(4)}
        if dHs is None or any(v is None for v in dq.values()): continue
        if cls=="U": derived["m0"].append((dq[0],-2*dHs))
        elif cls=="C1": derived["mperp1"].append((dq[1],-2*dHs))
        elif cls=="C2": derived["mperp2"].append((dq[2],-2*dHs))
        elif cls=="C3": derived["mperp3"].append((dq[3],-2*dHs))

    for key,pts in derived.items():
        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
