    uc=["event_id","a1","a2","a3","theta1","theta2","theta3","ud_source_status"]
    pc=["event_id","A1","A2","A3","B1","B2","B3","physical_source_status"]
    if list(ud.columns)!=uc or list(ph.columns)!=pc: raise ValueError("schema mismatch")
    if ud.event_id.duplicated().any() or ph.event_id.duplicated().any(): raise ValueError("duplicate event_id")
    if ud.event_id.tolist()!=ph.event_id.tolist(): raise ValueError("event alignment mismatch")
    if not (ud.ud_source_status=="RESOLVED").all(): raise ValueError("unresolved UD event")
    if not (ph.physical_source_status=="CAPTURED").all(): raise ValueError("uncaptured physical event")
    for c in uc[1:7]:
        if not set(ud[c].astype(int)).issubset({0,1}): raise ValueError("nonbinary UD")
    for c in pc[1:7]:
        if not set(ph[c].astype(int)).issubset({0,1}): raise ValueError("nonbinary physical")

def _stats(U,P):
    ma=np.all(U[:,:3]==P[:,:3],axis=1)
    mb=np.all(U[:,3:]==P[:,3:],axis=1)
    return np.array([np.sum(ma&mb),np.sum(ma),np.sum(mb)],dtype=int)

def score(ud_path,ph_path,guard):
    ud=pd.read_csv(ud_path); ph=pd.read_csv(ph_path); _validate(ud,ph)
    U=ud[["a1","a2","a3","theta1","theta2","theta3"]].astype(int).to_numpy()
    P=ph[["A1","A2","A3","B1","B2","B3"]].astype(int).to_numpy()
    N=len(U); obs=_stats(U,P)

    shifts=[d for d in range(1,N) if min(d,N-d)>guard]
    if len(shifts)+1<600:
        return {"verdict":"INSUFFICIENT_NULL_RESOLUTION","N":N,"allowed_shifts":len(shifts)}
    nt=np.array([_stats(U,np.roll(P,d,axis=0)) for d in shifts],dtype=int)
    pT=[(1+int(np.sum(nt[:,j]>=obs[j])))/(1+len(shifts)) for j in range(3)]

    shells=np.column_stack([P[:,:3].sum(axis=1),P[:,3:].sum(axis=1)])
    strata={}
    for i,h in enumerate(map(tuple,shells)):
        strata.setdefault(h,[]).append(i)

    rng=np.random.default_rng(SEED)
    ge=np.zeros(3,dtype=int)
    for _ in range(N_COND):
        Q=P.copy()
        for ids in strata.values():
            if len(ids)>1:
                ids=np.array(ids,dtype=int)
                src=ids.copy()
                rng.shuffle(src)
                Q[ids]=P[src]
        s=_stats(U,Q)
        ge += (s>=obs)
    pH=[(1+int(ge[j]))/(N_COND+1) for j in range(3)]

    allp=pT+pH
    if all(p<=ALPHA for p in allp):
        verdict="ST3S_CORRESPONDENCE_PASS"
    elif all(p<=ALPHA for p in pT) and not all(p<=ALPHA for p in pH):
        verdict="ST3S_SHELL_ONLY"
    else:
        verdict="ST3S_NO_CORRESPONDENCE"

    return {
        "verdict":verdict,"N":N,"guard":guard,"allowed_shifts":len(shifts),
        "conditional_randomizations":N_COND,"seed":SEED,
        "alpha_familywise":1/100,"alpha_each":ALPHA,
        "observed":{"S_AB":int(obs[0]),"S_A":int(obs[1]),"S_B":int(obs[2])},
        "p_temporal":{"AB":pT[0],"A":pT[1],"B":pT[2]},
        "p_shell_conditioned_address":{"AB":pH[0],"A":pH[1],"B":pH[2]}
    }

if __name__=="__main__":
    ap=argparse.ArgumentParser()
    ap.add_argument("--ud",required=True);ap.add_argument("--physical",required=True)
    ap.add_argument("--guard",required=True,type=int);ap.add_argument("--out",required=True)
    a=ap.parse_args()
    r=score(a.ud,a.physical,a.guard)
    with open(a.out,"w") as f:json.dump(r,f,indent=2)
    print(json.dumps(r,indent=2))

Verifies local release archives and every file listed by their package manifests against the machine-readable authority snapshot. #!/usr/bin/env python3
"""Verify a local mirror against UD_RELEASE_AUTHORITY_MANIFEST_v0.1.json."""

import hashlib
import json
import re
import sys
from pathlib import Path


def digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def entries(path: Path):
    if path.suffix == ".json":
        data = json.loads(path.read_text(encoding="utf-8"))
        for item in data.get("files", []):
            yield item.get("path") or item.get("filename") or item.get("file"), item["sha256"], item.get("bytes")
    else:
        for line in path.read_text(encoding="utf-8").splitlines():
            match = re.match(r"^([0-9a-f]{64})\s+\*?(.*)$", line.strip())
            if match:
                yield match.group(2), match.group(1), None


def main() -> int:
    if len(sys.argv) != 3:
        print("usage: verify_ud_release_authority.py MANIFEST_JSON MIRROR_DIR", file=sys.stderr)
        return 2
    authority = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
    mirror = Path(sys.argv[2])
    failures = []
    for release in authority["releases"]:
        archive = mirror / "releases" / release["archive"]
        if not archive.is_file():
            failures.append(f"missing archive: {archive}")
            continue
        if archive.stat().st_size != release["bytes"] or digest(archive) != release["sha256"]:
            failures.append(f"archive mismatch: {release['archive']}")
            continue
        outer = mirror / "release_extract" / archive.stem
        children = list(outer.iterdir()) if outer.is_dir() else []
        roots = [p for p in children if p.is_dir()]
        root = roots[0] if len(roots) == 1 and not any(p.is_file() for p in children) else outer
        manifest = root / release["manifest"]
        if not manifest.is_file():
            failures.append(f"missing package manifest: {release['archive']}")
            continue
        for relpath, expected, expected_bytes in entries(manifest):
            item = root / relpath
            if not item.is_file() or digest(item) != expected:
                failures.append(f"listed-file mismatch: {release['archive']}::{relpath}")
            elif expected_bytes is not None and item.stat().st_size != expected_bytes:
                failures.append(f"listed-file size mismatch: {release['archive']}::{relpath}")
    if failures:
        print("FAIL")
        print("\n".join(failures))
        return 1
    print(f"PASS: {len(authority['releases'])} archives and all listed package hashes verified")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

Executable scoring implementation for the preregistered comparison. Code and synthetic execution are not hardware evidence. #!/usr/bin/env python3
import json, math, sys
from pathlib import Path
import numpy as np
from scipy.optimize import minimize_scalar
from scipy.stats import chi2

N_REQUIRED=24
N_EACH=12
N_BLOCKS=6
ALPHA_ABS=0.01
DELTA_AICC_STRONG=10.0
K_PARAMS=1
D_H={'E0':0.25,'E1':0.75}

def _num(x,name):
    try:
        v=float(x)
    except Exception:
        raise ValueError(f'{name} must be numeric')
    if not math.isfinite(v):
        raise ValueError(f'{name} must be finite')
    return v

def _weighted_mean(vals, sigmas):
    vals=np.asarray(vals,float); sigmas=np.asarray(sigmas,float)
    w=1.0/(sigmas**2)
    m=float(np.sum(w*vals)/np.sum(w))
    u=float(math.sqrt(1.0/np.sum(w)))
    return m,u

def _validate(data):
    if not data.get('channel_independence_confirmed',False):
        return 'NO_SCORE_CHANNEL_INDEPENDENCE_FAIL',None
    if not data.get('custody_frozen',False):
        return 'NO_SCORE_CUSTODY_NOT_FROZEN',None
    if not data.get('uncertainty_model_complete',False):
        return 'NO_SCORE_UNCERTAINTY_MODEL_INCOMPLETE',None
    runs=data.get('runs')
    if not isinstance(runs,list):
        return 'NO_SCORE_SOURCE_INCOMPLETE',None
    primary=[r for r in runs if r.get('valid_primary') is True]
    if len(primary)!=N_REQUIRED:
        return 'NO_SCORE_PRIMARY_SET_INCOMPLETE',{'valid_primary_count':len(primary)}
    ids=[r.get('blind_run_id') for r in primary]
    if None in ids or len(set(ids))!=len(ids):
        return 'NO_SCORE_DUPLICATE_OR_MISSING_RUN_ID',None
    for r in primary:
        if r.get('event_id') not in ('E0','E1'):
            return 'NO_SCORE_EVENT_LABEL_INVALID',None
        if not r.get('calibration_in_control',False):
            return 'NO_SCORE_CALIBRATION_GATE_FAIL',{'blind_run_id':r.get('blind_run_id')}
        if not r.get('source_purity_pass',False):
            return 'NO_SCORE_SOURCE_PURITY_FAIL',{'blind_run_id':r.get('blind_run_id')}
        try:
            r['_epsilon']=_num(r.get('epsilon'),'epsilon')
            r['_ue']=_num(r.get('u_epsilon'),'u_epsilon')
            r['_lambda']=_num(r.get('Lambda'),'Lambda')
            r['_ul']=_num(r.get('u_Lambda'),'u_Lambda')
            r['_cov']=_num(r.get('cov_epsilon_lambda'),'cov_epsilon_lambda')
            r['_block']=int(r.get('block'))
        except Exception as exc:
            return 'NO_SCORE_SOURCE_INCOMPLETE',{'error':str(exc),'blind_run_id':r.get('blind_run_id')}
        if r['_ue']<=0 or r['_ul']<0:
            return 'NO_SCORE_UNCERTAINTY_INVALID',{'blind_run_id':r.get('blind_run_id')}
    counts={e:sum(r['event_id']==e for r in primary) for e in ('E0','E1')}
    if counts!={'E0':N_EACH,'E1':N_EACH}:
        return 'NO_SCORE_EVENT_BALANCE_FAIL',counts
    blocks=sorted(set(r['_block'] for r in primary))
    if blocks!=list(range(1,N_BLOCKS+1)):
        return 'NO_SCORE_BLOCK_STRUCTURE_FAIL',{'blocks':blocks}
    for b in blocks:
        bc={e:sum(r['_block']==b and r['event_id']==e for r in primary) for e in ('E0','E1')}
        if bc!={'E0':2,'E1':2}:
            return 'NO_SCORE_BLOCK_BALANCE_FAIL',{'block':b,'counts':bc}
    b_units={r.get('burden_units') for r in primary}; l_units={r.get('leakage_units') for r in primary}
    if len(b_units)!=1 or None in b_units:
        return 'NO_SCORE_BURDEN_UNITS_MISMATCH',{'units':list(b_units)}
    if len(l_units)!=1 or None in l_units:
        return 'NO_SCORE_LEAKAGE_UNITS_MISMATCH',{'units':list(l_units)}
    return None,primary

def _nll_H(k,y,ue,d):
    v=ue**2
    r=y-k*d
    return 0.5*float(np.sum(np.log(2*np.pi*v)+(r*r)/v))

def _fit_H(y,ue,d):
    w=1/(ue**2)
    den=float(np.sum(w*d*d))
    if den<=0: raise ValueError('H denominator zero')
    k=float(np.sum(w*d*y)/den)
    nll=_nll_H(k,y,ue,d)
    v=ue**2; res=y-k*d
    chi=float(np.sum(res*res/v))
    return k,nll,chi,res,v

def _fit_P(y,ue,x,ux,cov):
    sy=max(float(np.max(np.abs(y))),float(np.max(ue)),1e-12)
    sx=max(float(np.max(np.abs(x))),float(np.max(ux)),1e-12)
    scale=sy/sx
    bound=max(1000.0*scale,1e-9)
    def nll(k):
        v=ue**2+(k*k)*(ux**2)-2*k*cov
        if np.any(v<=0) or np.any(~np.isfinite(v)):
            return 1e300
        r=y-k*x
        return 0.5*float(np.sum(np.log(2*np.pi*v)+(r*r)/v))
    opt=minimize_scalar(nll,bounds=(-bound,bound),method='bounded',options={'xatol':1e-12,'maxiter':2000})
    if not opt.success or not math.isfinite(opt.fun):
        raise ValueError('PLB1 optimizer failed')
    k=float(opt.x)
    v=ue**2+(k*k)*(ux**2)-2*k*cov
    if np.any(v<=0): raise ValueError('PLB1 propagated variance nonpositive')
    res=y-k*x
    chi=float(np.sum(res*res/v))
    boundary=abs(k)>=0.999*bound
    return k,float(opt.fun),chi,res,v,bound,boundary

def _aicc(nll,n,k=1):
    if n<=k+1: return float('inf')
    return 2*nll+2*k+(2*k*(k+1))/(n-k-1)

def score(data):
    status,primary=_validate(data)
    if status:
        out={'status':status,'physical_promotion':0}
        if isinstance(primary,dict): out.update(primary)
        return out
    y=np.array([r['_epsilon'] for r in primary],float)
    ue=np.array([r['_ue'] for r in primary],float)
    x=np.array([r['_lambda'] for r in primary],float)
    ux=np.array([r['_ul'] for r in primary],float)
    cov=np.array([r['_cov'] for r in primary],float)
    d=np.array([D_H[r['event_id']] for r in primary],float)
    try:
        kH,nllH,chiH,resH,vH=_fit_H(y,ue,d)
        kP,nllP,chiP,resP,vP,bound,boundary=_fit_P(y,ue,x,ux,cov)
    except Exception as exc:
        return {'status':'NO_SCORE_NUMERICAL_FAILURE','error':str(exc),'physical_promotion':0}
    if boundary:
        return {'status':'NO_SCORE_NUMERICAL_BOUNDARY','kappa_P':kP,'search_bound':bound,'physical_promotion':0}
    df=len(primary)-K_PARAMS
    pH=float(chi2.sf(chiH,df)); pP=float(chi2.sf(chiP,df))
    aH=_aicc(nllH,len(primary),K_PARAMS); aP=_aicc(nllP,len(primary),K_PARAMS)
    delta=float(aP-aH)
    fitH=pH>=ALPHA_ABS; fitP=pP>=ALPHA_ABS
    if fitH and delta>=DELTA_AICC_STRONG:
        verdict='HCB1_PASS_EMPIRICAL_SCOPED'
    elif fitP and delta<=-DELTA_AICC_STRONG:
        verdict='PLB1_PASS_EMPIRICAL_SCOPED'
    elif (not fitH) and (not fitP):
        verdict='NEITHER_SIMPLE_BRIDGE'
    else:
        verdict='EMPIRICAL_INDETERMINATE'
    # Diagnostics by class
    cls={}
    for e in ('E0','E1'):
        rr=[r for r in primary if r['event_id']==e]
        em,eu=_weighted_mean([r['_epsilon'] for r in rr],[r['_ue'] for r in rr])
        # leakage mean uses positive u; if exact zero uncertainties all, arithmetic mean and u=0
        lus=[r['_ul'] for r in rr]
        if all(u>0 for u in lus):
            lm,lu=_weighted_mean([r['_lambda'] for r in rr],lus)
        else:
            lm=float(np.mean([r['_lambda'] for r in rr])); lu=0.0
        cls[e]={'epsilon_mean':em,'u_epsilon_mean':eu,'Lambda_mean':lm,'u_Lambda_mean':lu}
    RB=None; RL=None; zL=None
    if cls['E0']['epsilon_mean']!=0:
        RB=cls['E1']['epsilon_mean']/cls['E0']['epsilon_mean']
    if cls['E0']['Lambda_mean']!=0:
        RL=cls['E1']['Lambda_mean']/cls['E0']['Lambda_mean']
    denom=math.sqrt(cls['E0']['u_Lambda_mean']**2+cls['E1']['u_Lambda_mean']**2)
    if denom>0: zL=(cls['E1']['Lambda_mean']-cls['E0']['Lambda_mean'])/denom
    per=[]
    for i,r in enumerate(primary):
        per.append({
            'blind_run_id':r['blind_run_id'],'block':r['_block'],'event_id':r['event_id'],
            'z_PLB1':float(resP[i]/math.sqrt(vP[i])),
            'z_HCB1':float(resH[i]/math.sqrt(vH[i]))
        })
    return {
        'status':verdict,
        'n':len(primary),'df_gof':df,
        'protocol':{'alpha_absolute_fit':ALPHA_ABS,'strong_delta_AICc':DELTA_AICC_STRONG,'fitted_parameters_per_model':1,'extra_scatter_fitted':False},
        'PLB1':{'kappa_hat':kP,'NLL':nllP,'chi2':chiP,'p_gof':pP,'absolute_fit_pass':fitP,'AICc':aP},
        'HCB1':{'kappa_hat':kH,'NLL':nllH,'chi2':chiH,'p_gof':pH,'absolute_fit_pass':fitH,'AICc':aH},
        'delta_AICc_P_minus_H':delta,
        'class_diagnostics':cls,
        'R_B_weighted_means':RB,'R_Lambda_weighted_means':RL,'leakage_stationarity_z':zL,
        'run_standardized_residuals':per,
        'physical_promotion':0
    }

if __name__=='__main__':
    if len(sys.argv)!=2:
        raise SystemExit('usage: empirical_joint_source_event_scorer_v0.2.py input.json')
    print(json.dumps(score(json.loads(Path(sys.argv[1]).read_text())),indent=2,sort_keys=True))

